import { test, expect } from '@playwright/test';

test('modifies the real response', async ({ page }) => {
  await page.route('**/api/todos', async (route) => {
    const response = await route.fetch();
    const json = await response.json();
    json.todos.push({ id: 99, title: 'Injected by route', done: false });
    await route.fulfill({ response, json });
  });
  await page.goto('/todos');
  await expect(page.getByText('Injected by route')).toBeVisible();
  await expect(page.getByText('3 items left')).toBeVisible();
});

test('network failure shows the error state', async ({ page }) => {
  await page.route('**/api/todos', (route) => route.abort());
  await page.goto('/todos');
  await expect(page.getByRole('alert')).toHaveText('Could not load todos. Please try again.');
});
